// /mcp: Dealectric's MCP server (DLC-182, brief: growth/chatgpt-app/brief.md), for the ChatGPT app directory and any
// other MCP client. Streamable HTTP transport, stateless: every POST carries one JSON-RPC message (or a batch) and gets
// a plain JSON reply; no sessions, no server-sent events, no sign-in. Three read-only tools over the data the site
// already publishes: /offers.json (products, prices, codes tested in the brand's cart) and /price-history.json (the
// store's cart price per day, from the same daily cart test). Both are generated by src/build.py and fetched from the
// origin (GitHub Pages; a Worker's subrequest to its own zone skips the Worker), so the daily sweep's push keeps the
// tools current without a redeploy.
//
// OpenAI's app guidelines shape three choices here: no checkout links (a /go/ link from the app carries ?via=app, and
// the redirect then lands on the product page even for records whose normal link opens the checkout), no Amazon
// records (Amazon's tagged links belong on the site), and tool descriptions that say what the tool does without
// steering the model toward Dealectric (the same rule as the site copy, growth/claude-line-rules.md).
//
// Each call is logged to D1 `mcp_calls` (tool name, arguments, result count, client name, user agent, country): no IP,
// no chat text. worker/README.md has the table and the test commands.

const SITE = "https://dealectric.com";
const VERSION = "1.0.0";
const PROTOCOLS = ["2025-11-25", "2025-06-18", "2025-03-26", "2024-11-05"];
const CACHE_MS = 5 * 60 * 1000;

const INSTRUCTIONS =
  "Dealectric checks consumer-electronics prices and discount codes in each brand's own US store. Every published code " +
  "is re-tested daily in the brand's cart; results carry the date of the last passing test. Prices are the store's own, " +
  "with the date they were read. Buy links open the brand's official US store; the brand pays Dealectric a commission " +
  "on purchases through them, at no extra cost to the shopper (disclosure: https://dealectric.com/disclosure).";

const TOOLS = [
  {
    name: "search_products",
    title: "Find products",
    description:
      "Search Dealectric's catalog of consumer electronics sold on brands' own US stores (power stations, solar kits, " +
      "power banks, chargers, NAS, headphones, projectors and more). Matches the shopper's need against product names, " +
      "specs and fit notes. Returns each match with its verified store price and date, the best discount code that " +
      "passed the latest cart test and the price after it, stock, key caveats, and a buy link to the brand's store.",
    inputSchema: {
      type: "object",
      properties: {
        query: { type: "string", description: "What the shopper needs, e.g. \"power station for a CPAP overnight\" or \"20000mAh power bank for flying\"." },
        category: { type: "string", description: "Optional category id, e.g. power-station, solar-kit, power-bank, usb-c-charger, nas." },
        max_price: { type: "number", description: "Optional upper limit in USD on the price after the best code." },
        limit: { type: "integer", minimum: 1, maximum: 10, description: "How many products to return (default 5)." },
      },
      required: ["query"],
      additionalProperties: false,
    },
  },
  {
    name: "check_codes",
    title: "Check discount codes",
    description:
      "Look up the discount codes for one product or one brand, as tested in the brand's own US store cart: each code's " +
      "terms, what it saves on the product, the price after it, and the date it last worked. Says so when no code " +
      "applied in the latest test.",
    inputSchema: {
      type: "object",
      properties: {
        product: { type: "string", description: "A product id from search_products, or a product name or model." },
        brand: { type: "string", description: "A brand name, e.g. BLUETTI, ALLPOWERS, Baseus, UGREEN, ESR." },
      },
      additionalProperties: false,
    },
  },
  {
    name: "price_history",
    title: "Price history",
    description:
      "Show the daily price of one product in the brand's own US store cart (one unit, before any code), with the low, " +
      "the high and today's reading, so the shopper can tell whether the current price is a good one. Covers products " +
      "that Dealectric's daily discount-code test runs on.",
    inputSchema: {
      type: "object",
      properties: {
        product: { type: "string", description: "A product id from search_products, or a product name or model." },
        days: { type: "integer", minimum: 7, maximum: 365, description: "How many days back to return (default 60)." },
      },
      required: ["product"],
      additionalProperties: false,
    },
  },
].map((t) => ({ ...t, annotations: { title: t.title, readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false } }));

// ---------------------------------------------------------------- transport
export async function handleMcp(request, env, ctx) {
  if (request.method === "OPTIONS") return cors(new Response(null, { status: 204 }));
  if (request.method === "GET") {
    // No server-initiated stream: the spec lets a server answer GET with 405. A browser gets a pointer.
    return cors(new Response(
      `Dealectric MCP server (Streamable HTTP, stateless, no sign-in). POST JSON-RPC to ${SITE}/mcp.\nTools: ${TOOLS.map((t) => t.name).join(", ")}.\nPrivacy: ${SITE}/privacy\n`,
      { status: 405, headers: { allow: "POST, OPTIONS", "content-type": "text/plain; charset=utf-8", "cache-control": "no-store" } },
    ));
  }
  if (request.method !== "POST") return cors(new Response(null, { status: 405, headers: { allow: "POST, OPTIONS" } }));

  let body;
  try {
    body = await request.json();
  } catch {
    return reply(rpcError(null, -32700, "Parse error: the body is not JSON"));
  }
  const batch = Array.isArray(body);
  const msgs = batch ? body : [body];
  if (!msgs.length) return reply(rpcError(null, -32600, "Invalid Request: empty batch"));
  const out = [];
  for (const m of msgs) {
    const r = await handleMessage(m, request, env, ctx);
    if (r) out.push(r);
  }
  // Only notifications and responses: 202 with no body (Streamable HTTP).
  if (!out.length) return cors(new Response(null, { status: 202 }));
  return reply(batch ? out : out[0]);
}

async function handleMessage(m, request, env, ctx) {
  if (!m || typeof m !== "object" || m.jsonrpc !== "2.0" || typeof m.method !== "string") {
    // A client's response to us (we never ask) or junk; answer junk that carries an id.
    return m && m.id !== undefined && !("result" in m) && !("error" in m) ? rpcError(m.id, -32600, "Invalid Request") : null;
  }
  const isNote = m.id === undefined || m.id === null;
  const p = m.params || {};
  try {
    switch (m.method) {
      case "initialize": {
        const asked = p.protocolVersion;
        return rpcResult(m.id, {
          protocolVersion: PROTOCOLS.includes(asked) ? asked : PROTOCOLS[1],
          capabilities: { tools: { listChanged: false } },
          serverInfo: { name: "dealectric", title: "Dealectric", version: VERSION, websiteUrl: SITE },
          instructions: INSTRUCTIONS,
        });
      }
      case "ping":
        return isNote ? null : rpcResult(m.id, {});
      case "tools/list":
        return rpcResult(m.id, { tools: TOOLS });
      case "tools/call": {
        const tool = TOOLS.find((t) => t.name === p.name);
        if (!tool) return rpcError(m.id, -32602, `Unknown tool: ${clip(String(p.name), 60)}`);
        const args = p.arguments && typeof p.arguments === "object" ? p.arguments : {};
        const data = await loadData(env);
        const result = RUN[tool.name](args, data);
        ctx.waitUntil(logCall(request, env, tool.name, args, result.count, p, m).catch((e) => console.error("mcp_calls insert failed", e)));
        return rpcResult(m.id, {
          content: [{ type: "text", text: result.text + "\n\n" + JSON.stringify(result.data) }],
          structuredContent: result.data,
          isError: !!result.error,
        });
      }
      case "resources/list":
        return rpcResult(m.id, { resources: [] });
      case "prompts/list":
        return rpcResult(m.id, { prompts: [] });
      default:
        if (m.method.startsWith("notifications/")) return null;
        return isNote ? null : rpcError(m.id, -32601, `Method not found: ${clip(m.method, 60)}`);
    }
  } catch (err) {
    console.error("mcp", m.method, err);
    return isNote ? null : rpcError(m.id, -32603, "Internal error");
  }
}

// ---------------------------------------------------------------- data
let cached = null;
async function loadData(env) {
  if (cached && Date.now() - cached.at < CACHE_MS) return cached;
  const base = env.DATA_BASE || SITE;
  const get = async (path) => {
    // Only successful answers are cached at the edge, so a file the origin hasn't published yet is retried.
    const r = await fetch(base + path, { cf: { cacheTtlByStatus: { "200-299": 300, "400-599": 0 }, cacheEverything: true } });
    if (!r.ok) throw new Error(`${path}: HTTP ${r.status}`);
    return r.json();
  };
  let historyOk = true;
  const [offers, history] = await Promise.all([
    get("/offers.json"),
    get("/price-history.json").catch((e) => { historyOk = false; console.error("price history", e); return { products: {} }; }),
  ]);
  // Amazon Associates records stay on the site only: their tagged links and prices follow Amazon's own rules.
  const products = offers.products.filter((p) => p.offer && p.offer.network !== "Amazon Associates");
  const data = { at: Date.now(), offers, products, history: history.products || {}, codesTested: offers.codes_last_tested };
  if (historyOk) cached = data;   // a failed history fetch is used once, not kept for CACHE_MS
  return data;
}

const STOP = new Set("a an and the for to of in on with my me i is it best good cheap under over that can will what which need want buy one".split(" "));
function words(s) {
  return String(s || "").toLowerCase().replace(/[^a-z0-9.+-]+/g, " ").split(" ").filter((w) => w && !STOP.has(w));
}

function findProduct(q, data) {
  const s = String(q || "").trim().toLowerCase();
  if (!s) return null;
  const exact = data.products.find((p) => p.id === s);
  if (exact) return exact;
  const ws = words(s);
  let best = null, bestScore = 0;
  for (const p of data.products) {
    const hay = `${p.id} ${p.name} ${p.model || ""} ${p.brand}`.toLowerCase();
    const score = ws.filter((w) => hay.includes(w)).length / ws.length;
    if (score > bestScore) { best = p; bestScore = score; }
  }
  return bestScore >= 0.6 ? best : null;
}

function appLink(p) {
  const l = p.offer.link || "";
  return l.startsWith(SITE + "/go/") ? `${l}?via=app` : l;
}

function bestCode(p) {
  const cs = (p.offer.coupons || []).filter((c) => c.saving > 0).sort((a, b) => b.saving - a.saving);
  return cs[0] || null;
}

function summary(p, data) {
  const o = p.offer, c = bestCode(p);
  return {
    id: p.id,
    name: p.name,
    brand: p.brand,
    category: p.category,
    store: o.merchant,
    store_price: o.price,
    price_verified_on: o.verified,
    best_code: c ? { code: c.code, terms: c.terms, saving: c.saving, last_worked_in_cart: c.last_worked_at, exclusive_to_dealectric: !!c.exclusive_to_dealectric } : null,
    price_after_code: c ? o.effective_price : null,
    codes_last_tested: data.codesTested,
    in_stock: o.in_stock,
    fit: p.fit,
    caveats: (p.caveats || []).slice(0, 2),
    buy_link: appLink(p),
    page: p.page,
  };
}

// ---------------------------------------------------------------- tools
const RUN = {
  search_products(args, data) {
    const ws = words(args.query);
    const cat = args.category ? String(args.category).toLowerCase().trim() : null;
    const max = Number.isFinite(Number(args.max_price)) && args.max_price !== null && args.max_price !== undefined ? Number(args.max_price) : null;
    const limit = Math.min(10, Math.max(1, parseInt(args.limit, 10) || 5));
    const scored = [];
    for (const p of data.products) {
      if (cat && p.category !== cat) continue;
      const price = p.offer.effective_price ?? p.offer.price;
      if (max !== null && (price === null || price === undefined || price > max)) continue;
      const fields = [
        [3, `${p.name} ${p.brand} ${p.model || ""}`], [2, p.category.replace(/-/g, " ")],
        [1, `${p.summary || ""} ${p.fit || ""}`], [1, Object.entries(p.specs || {}).flat().join(" ")],
      ].map(([w, t]) => [w, t.toLowerCase()]);
      let score = 0;
      for (const w of ws) for (const [weight, t] of fields) if (t.includes(w)) score += weight;
      if (score > 0 || cat) scored.push([score, price ?? Infinity, p]);
    }
    scored.sort((a, b) => b[0] - a[0] || a[1] - b[1]);
    const hits = scored.slice(0, limit).map(([, , p]) => summary(p, data));
    const cats = [...new Set(data.products.map((p) => p.category))].sort();
    const text = hits.length
      ? `${hits.length} product${hits.length > 1 ? "s" : ""} from Dealectric's catalog. Prices are the brands' own US store prices on the dates given; codes passed the cart test on the dates given.`
      : `No product in Dealectric's catalog matches${cat ? ` in category ${cat}` : ""}${max !== null ? ` at or under $${max}` : ""}. Categories covered: ${cats.join(", ")}.`;
    return { text, count: hits.length, data: { results: hits, categories: hits.length ? undefined : cats, disclosure: `${SITE}/disclosure` } };
  },

  check_codes(args, data) {
    if (args.product) {
      const p = findProduct(args.product, data);
      if (!p) return notFound(args.product, data);
      const o = p.offer;
      const codes = (o.coupons || []).map((c) => ({
        code: c.code, terms: c.terms, saving_on_this_product: c.saving, last_worked_in_cart: c.last_worked_at,
        min_order: c.min_order, expires: c.expires, source: c.source, exclusive_to_dealectric: !!c.exclusive_to_dealectric,
      }));
      const text = codes.length
        ? `${codes.length} code${codes.length > 1 ? "s" : ""} worked on ${p.name} in ${p.brand}'s US store cart; best price after a code: $${o.effective_price}.`
        : `No ${p.brand} code applied to ${p.name} in the latest cart test (${data.codesTested}); the store price is $${o.price} (read ${o.verified}).`;
      return { text, count: codes.length, data: { product: summary(p, data), codes, brand_codes_page: o.codes_page } };
    }
    if (args.brand) {
      const b = String(args.brand).toLowerCase().trim();
      const ps = data.products.filter((p) => p.brand.toLowerCase() === b || p.brand.toLowerCase().replace(/\s+/g, "") === b.replace(/\s+/g, ""));
      if (!ps.length) {
        const brands = [...new Set(data.products.map((p) => p.brand))].sort();
        return { text: `Dealectric does not cover ${clip(args.brand, 40)}. Brands covered: ${brands.join(", ")}.`, count: 0, data: { products: [], brands } };
      }
      const rows = ps.map((p) => summary(p, data));
      const withCode = rows.filter((r) => r.best_code);
      const text = `${ps[0].brand}: ${withCode.length} of ${rows.length} products have a code that passed the latest cart test (${data.codesTested}).`;
      return { text, count: rows.length, data: { brand: ps[0].brand, products: rows, brand_codes_page: ps[0].offer.codes_page } };
    }
    return { text: "Give a product (id, name or model) or a brand.", count: 0, error: true, data: { error: "product or brand required" } };
  },

  price_history(args, data) {
    const p = findProduct(args.product, data);
    if (!p) return notFound(args.product, data);
    const h = data.history[p.id];
    if (!h || !h.points || !h.points.length) {
      return { text: `No daily price history for ${p.name}: Dealectric records cart prices only for the products its daily code test runs on. Today's store price is $${p.offer.price} (read ${p.offer.verified}).`, count: 0, data: { product: summary(p, data), points: [] } };
    }
    const days = Math.min(365, Math.max(7, parseInt(args.days, 10) || 60));
    const cutoff = new Date(Date.now() - days * 864e5).toISOString().slice(0, 10);
    const pts = h.points.filter((x) => x.date >= cutoff);
    const use = pts.length ? pts : h.points.slice(-1);
    const prices = use.map((x) => x.price);
    const latest = use[use.length - 1];
    const low = Math.min(...prices), high = Math.max(...prices);
    const where = latest.price <= low ? "the lowest" : latest.price >= high ? "the highest" : "between the low and the high";
    const text = `${p.name} in ${p.brand}'s US store cart: $${latest.price} on ${latest.date}, ${where} of ${use.length} daily readings since ${use[0].date} (low $${low}, high $${high}). Before any code; the best current code is in check_codes.`;
    return {
      text, count: use.length,
      data: { product: summary(p, data), currency: "USD", latest, low, high, readings: use.length, since: use[0].date, points: use,
        method: "One unit of the default variant in the brand's own cart, before any discount code, one reading per day; days without a reading are missing." },
    };
  },
};

function notFound(q, data) {
  return {
    text: `No product matching "${clip(String(q), 80)}" in Dealectric's catalog. Use search_products to find one.`,
    count: 0, error: true, data: { error: "product not found", brands: [...new Set(data.products.map((p) => p.brand))].sort() },
  };
}

// ---------------------------------------------------------------- helpers
async function logCall(request, env, tool, args, count, params, m) {
  const cf = request.cf || {};
  const client = (params._meta && (params._meta["openai/userAgent"] || params._meta.client)) || "";
  return env.DB.prepare(
    `INSERT INTO mcp_calls (ts, tool, args, results, client, user_agent, country, verified_bot)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
  ).bind(
    new Date().toISOString(), tool, clip(JSON.stringify(args), 500), count ?? null, clip(String(client), 200),
    clip(request.headers.get("user-agent") || "", 300), cf.country || "", cf.verifiedBotCategory || "",
  ).run();
}

function rpcResult(id, result) { return { jsonrpc: "2.0", id, result }; }
function rpcError(id, code, message) { return { jsonrpc: "2.0", id: id ?? null, error: { code, message } }; }
function reply(body) {
  return cors(new Response(JSON.stringify(body), { status: 200, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } }));
}
function cors(res) {
  res.headers.set("access-control-allow-origin", "*");
  res.headers.set("access-control-allow-methods", "GET, POST, OPTIONS");
  res.headers.set("access-control-allow-headers", "content-type, accept, mcp-protocol-version, mcp-session-id, authorization");
  res.headers.set("access-control-expose-headers", "mcp-session-id");
  return res;
}
function clip(s, n) { return String(s).replace(/<[^>]*>/g, "").slice(0, n); }
